//! Complete compiled schema-69 family registry, independent of writable schema upgrades.
//! The catalog is frozen from the registered original SQL; caller input cannot extend it.
use crate::storage_inventory::reader::{ColumnKind, ColumnSpec, TableSpec};
use crate::{JournalError, Result};
use serde::Serialize;
use std::collections::BTreeSet;

#[derive(Clone, Copy, Debug, Eq, PartialEq, Serialize)]
pub enum NativeHistoryColumnKind {
    HexText(usize),
    Utf8 { min: usize, max: usize },
    NonnegativeInteger,
    BoundedJson(usize),
}
#[derive(Clone, Copy, Debug, Eq, PartialEq, Serialize)]
pub struct NativeHistoryColumnSpec {
    pub name: &'static str,
    pub kind: NativeHistoryColumnKind,
    pub primary_key: usize,
    pub not_null: bool,
    pub default: Option<&'static str>,
}
#[derive(Clone, Copy, Debug, Eq, PartialEq, Serialize)]
pub struct NativeHistorySliceSpec {
    pub source: &'static str,
    pub tables: &'static [&'static str],
}
#[derive(Clone, Copy, Debug, Eq, PartialEq, Serialize)]
pub struct NativeHistoryCatalogDefinition {
    pub kind: &'static str,
    pub name: &'static str,
    pub table: &'static str,
    pub sql: Option<&'static str>,
}
#[derive(Clone, Copy, Debug, Eq, PartialEq, Serialize)]
pub(crate) enum NativeHistoryOwnerRelation {
    Anchor,
    Child {
        parent: &'static str,
        columns: &'static [(&'static str, &'static str)],
    },
    LocalIdentityOrTypedHistory,
}
#[derive(Clone, Copy, Debug, Eq, PartialEq, Serialize)]
pub(crate) enum NativeHistoryDirectReference {
    None,
    CasChunk {
        column: &'static str,
        length_column: Option<&'static str>,
    },
    WholeFileDigest {
        column: &'static str,
    },
}
#[derive(Clone, Copy, Debug, Eq, PartialEq, Serialize)]
pub struct NativeHistoryTableRule {
    pub table: &'static str,
    pub family: &'static str,
    pub slice: usize,
    pub columns: &'static [NativeHistoryColumnSpec],
    pub clock_columns: &'static [&'static str],
    pub signature_columns: &'static [&'static str],
    pub native_identity_columns: &'static [&'static str],
    pub root_bound_columns: &'static [&'static str],
    pub(crate) owner: NativeHistoryOwnerRelation,
    pub(crate) direct_reference: NativeHistoryDirectReference,
    pub(crate) audited_embedded_columns: &'static [&'static str],
    pub(crate) portable_state: bool,
}
#[derive(Clone, Copy)]
pub struct NativeHistoryFamilyRegistry {
    _compiled: (),
}
impl NativeHistoryFamilyRegistry {
    pub const SOURCE_SCHEMA: u32 = 69;
    pub const TABLE_COUNT: usize = 141;
    pub const INDEX_COUNT: usize = 170;
    pub const TRIGGER_COUNT: usize = 847;
    pub const FAMILY_COUNT: usize = 22;
    pub const SLICE_COUNT: usize = 27;
    pub fn schema69() -> Self {
        Self { _compiled: () }
    }
    pub fn tables(self) -> &'static [NativeHistoryTableRule] {
        TABLE_RULES
    }
    pub fn families(self) -> &'static [&'static str] {
        FAMILIES
    }
    pub fn slices(self) -> &'static [NativeHistorySliceSpec] {
        SLICES
    }
    pub fn catalog(self) -> &'static [NativeHistoryCatalogDefinition] {
        CATALOG
    }
    pub(crate) fn table(self, name: &str) -> Result<&'static NativeHistoryTableRule> {
        TABLE_RULES
            .iter()
            .find(|table| table.table == name)
            .ok_or(JournalError::Invariant(
                "native history unknown compiled family table",
            ))
    }
    pub(crate) fn row_specs() -> Vec<TableSpec> {
        [
            slice_00::TABLES,
            slice_01::TABLES,
            slice_02::TABLES,
            slice_03::TABLES,
            slice_04::TABLES,
            slice_05::TABLES,
            slice_06::TABLES,
            slice_07::TABLES,
            slice_08::TABLES,
            slice_09::TABLES,
            slice_10::TABLES,
            slice_11::TABLES,
            slice_12::TABLES,
            slice_13::TABLES,
            slice_14::TABLES,
            slice_15::TABLES,
            slice_16::TABLES,
            slice_17::TABLES,
            slice_18::TABLES,
            slice_19::TABLES,
            slice_20::TABLES,
            slice_21::TABLES,
            slice_22::TABLES,
            slice_23::TABLES,
            slice_24::TABLES,
            slice_25::TABLES,
            slice_26::TABLES,
        ]
        .concat()
    }
    pub(crate) fn verify_complete(self) -> Result<()> {
        let specs = Self::row_specs();
        let names: BTreeSet<_> = specs.iter().map(|spec| spec.name).collect();
        let rules: BTreeSet<_> = TABLE_RULES.iter().map(|rule| rule.table).collect();
        let families: BTreeSet<_> = TABLE_RULES.iter().map(|rule| rule.family).collect();
        let sliced: Vec<_> = SLICES
            .iter()
            .flat_map(|slice| slice.tables.iter().copied())
            .collect();
        if specs.len() != Self::TABLE_COUNT
            || names.len() != Self::TABLE_COUNT
            || TABLE_RULES.len() != Self::TABLE_COUNT
            || names != rules
            || families.len() != Self::FAMILY_COUNT
            || families != FAMILIES.iter().copied().collect()
            || SLICES.len() != Self::SLICE_COUNT
            || sliced.len() != Self::TABLE_COUNT
            || sliced.iter().copied().collect::<BTreeSet<_>>() != names
            || CATALOG.len() != Self::TABLE_COUNT + Self::INDEX_COUNT + Self::TRIGGER_COUNT
            || CATALOG.iter().filter(|item| item.kind == "table").count() != Self::TABLE_COUNT
            || CATALOG.iter().filter(|item| item.kind == "index").count() != Self::INDEX_COUNT
            || CATALOG.iter().filter(|item| item.kind == "trigger").count() != Self::TRIGGER_COUNT
        {
            return Err(JournalError::Invariant(
                "native history compiled registry incomplete",
            ));
        }
        for spec in &specs {
            let rule = self.table(spec.name)?;
            if spec.columns.len() != rule.columns.len()
                || !SLICES[rule.slice].tables.contains(&spec.name)
            {
                return Err(JournalError::Invariant(
                    "native history compiled slice or column differs",
                ));
            }
            for (physical, public) in spec.columns.iter().zip(rule.columns) {
                let kind = match physical.kind {
                    ColumnKind::Text(n) if n == crate::MAX_OPERATION_BYTES => {
                        NativeHistoryColumnKind::BoundedJson(n)
                    }
                    ColumnKind::Text(n) => NativeHistoryColumnKind::HexText(n),
                    ColumnKind::Utf8 { min, max } => NativeHistoryColumnKind::Utf8 { min, max },
                    ColumnKind::Integer => NativeHistoryColumnKind::NonnegativeInteger,
                };
                if physical.name != public.name
                    || kind != public.kind
                    || physical.primary_key != public.primary_key
                    || physical.not_null != public.not_null
                    || physical.default != public.default
                {
                    return Err(JournalError::Invariant(
                        "native history compiled column mismatch",
                    ));
                }
            }
            if let NativeHistoryOwnerRelation::Child { parent, columns } = rule.owner {
                let parent = self.table(parent)?;
                let mut parent_keys: Vec<_> = parent
                    .columns
                    .iter()
                    .filter(|column| column.primary_key != 0)
                    .collect();
                parent_keys.sort_by_key(|column| column.primary_key);
                if columns.len() != parent_keys.len()
                    || columns.iter().zip(parent_keys).any(|((from, to), key)| {
                        *to != key.name || !rule.columns.iter().any(|column| column.name == *from)
                    })
                {
                    return Err(JournalError::Invariant(
                        "native history compiled owner link mismatch",
                    ));
                }
            }
        }
        Ok(())
    }
}

